export class ApplicationContractClient {
    request;
    constructor(request) {
        this.request = request;
    }
    get(id) { return this.request(`/v1/applications/${encodeURIComponent(id)}/contract`); }
    evaluate(id, outcome) { return this.request(`/v1/applications/${encodeURIComponent(id)}/contract/evaluate`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ outcome }) }); }
    readiness(id) { return this.request(`/v1/applications/${encodeURIComponent(id)}/contract/readiness`); }
    gaps(id) { return this.request(`/v1/applications/${encodeURIComponent(id)}/contract/gaps`); }
    question(id) { return this.request(`/v1/applications/${encodeURIComponent(id)}/contract/question`); }
    end(id) { return this.request(`/v1/applications/${encodeURIComponent(id)}/contract/end`, { method: 'POST' }); }
    construct(id) { return this.request(`/v1/applications/${encodeURIComponent(id)}/contract/construct`, { method: 'POST' }); }
    patch(id, patch) { return this.request(`/v1/applications/${encodeURIComponent(id)}/contract/patch`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(patch) }); }
}
